<!DOCTYPE html> <html lang="pt-BR" class="dark"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>GoCine - TMDb em Português</title> <!-- Tailwind CSS CDN --> <script src="https://cdn.tailwindcss.com"></script> <!-- Lucide Icons CDN --> <script src="https://unpkg.com/lucide@latest"></script> <script> tailwind.config = { darkMode: 'class', theme: { extend: { colors: { brand: { red: '#E50914', hoverRed: '#B80710', dark: '#0F0F0F', card: '#181818', border: '#2A2A2A' } } } } } </script> </head> <body class="bg-brand-dark text-white font-sans min-h-screen flex flex-col selection
<!-- Modal de Configuração da Chave do TMDb --> <div id="key-modal" class="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md hidden"> <div class="bg-brand-card p-8 rounded-xl border border-brand-border w-full max-w-md shadow-2xl relative text-center"> <div class="inline-flex p-3 bg-brand-red/10 rounded-full mb-4"> <i data-lucide="key" class="w-8 h-8 text-brand-red"></i> </div> <h2 class="text-2xl font-bold text-white mb-2">Chave de API do TMDb</h2> <p class="text-xs text-gray-400 mb-6 leading-relaxed"> O TMDb exige uma chave gratuita para carregar imagens e dados em português. Cole sua chave v3 abaixo: </p> <form onsubmit="saveApiKey(event)" class="space-y-4"> <input type="text" id="api-key-input" required placeholder="Cole sua v3 API Key do TMDb aqui" class="w-full bg-brand-dark border border-brand-border rounded px-4 py-2.5 text-sm focus:outline-none focus:border-brand-red text-white text-center"> <button type="submit" class="w-full bg-brand-red hover:bg-brand-hoverRed text-white font-bold py-2.5 px-4 rounded transition duration-200 text-sm"> Salvar e Carregar Filmes </button> </form> <p class="mt-4 text-xs text-gray-500"> Não tem uma chave? <a href="https://www.themoviedb.org/signup" target="_blank" class="text-brand-red underline">Crie uma grátis no TMDb</a> </p> </div> </div>
<!-- Cabeçalho / Navegação --> <header class="border-b border-brand-border bg-brand-dark/95 backdrop-blur sticky top-0 z-40"> <div class="max-w-7xl mx-auto px-4 py-4 flex flex-wrap items-center justify-between gap-4"> <div class="flex items-center space-x-8"> <h1 class="text-2xl font-black tracking-wider text-brand-red cursor-pointer" onclick="showSection('search')">GOCINE</h1> <nav class="hidden md:flex space-x-6 text-sm font-medium"> <button onclick="showSection('search')" class="hover:text-brand-red transition">Catálogo PT-BR</button> <button onclick="showSection('liked')" class="hover:text-brand-red transition">Curtidos</button> <button onclick="showSection('watched')" class="hover:text-brand-red transition">Já Assisti</button> <button onclick="showSection('watchlist')" class="hover:text-brand-red transition">Pretendo Assistir</button> </nav> </div>
<!-- Campo de Pesquisa em Tempo Real --> <div class="flex items-center space-x-3 flex-1 max-w-md"> <div class="relative w-full"> <input type="text" id="search-input" oninput="handleSearch(event)" placeholder="Buscar filme ou série em português..." class="w-full bg-brand-card border border-brand-border rounded-full py-2 pl-10 pr-4 text-sm text-white focus:outline-none focus:border-brand-red"> <i data-lucide="search" class="w-4 h-4 absolute left-3 top-2.5 text-gray-400"></i> </div> <button onclick="openKeyModal()" class="text-gray-400 hover:text-white p-2 border border-brand-border rounded-full bg-brand-card" title="Alterar Chave de API"> <i data-lucide="key" class="w-4 h-4"></i> </button> </div> </div>
<!-- Navegação Mobile --> <div class="flex md:hidden justify-around border-t border-brand-border py-2 text-xs"> <button onclick="showSection('search')" class="hover:text-brand-red">Catálogo</button> <button onclick="showSection('liked')" class="hover:text-brand-red">Curtidos</button> <button onclick="showSection('watched')" class="hover:text-brand-red">Já Assisti</button> <button onclick="showSection('watchlist')" class="hover:text-brand-red">Pretendo</button> </div> </he
<!-- Conteúdo Principal --> <main class="flex-1 max-w-7xl w-full mx-auto p-4 md:p-6"> <div class="flex items-center justify-between mb-6 border-b border-brand-border pb-4"> <h2 id="section-title" class="text-2xl font-bold text-white flex items-center gap-2"> <i data-lucide="film" class="text-brand-red"></i> Filmes Populares (PT-BR) </h2> <span id="item-count" class="text-sm text-gray-400"></span> </div>ader>
<!-- Grid de Filmes --> <div id="movies-grid" class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6"> <!-- Preenchido via JS --> </div> </main>
<!-- Modal de Detalhes --> <div id="details-modal" class="fixed inset-0 z-50 hidden bg-black/85 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto"> <div class="bg-brand-card border border-brand-border rounded-xl max-w-2xl w-full p-6 relative my-8"> <button onclick="closeDetailsModal()" class="absolute top-4 right-4 text-gray-400 hover:text-white"> <i data-lucide="x" class="w-6 h-6"></i> </button> <div id="modal-content"> <!-- Detalhes do filme selecionado --> </div> </div> </div>
<!-- Lógica JavaScript Principal com API TMDb e Sincronização PHP --> <script> const TMDB_BASE_URL = 'https://api.themoviedb.org/3'; const IMAGE_BASE_URL = 'https://image.tmdb.org/t/p/w500'; let apiKey = localStorage.getItem('gocine_tmdb_key') || ''; let currentSection = 'search';
 let userLibrary = { liked: [], watched: [], watchlist: [] }; // Sincroniza a biblioteca local com a API PHP (Banco de Dados) async function fetchServerLibrary() { try { const res = await fetch('index.php?action=get_library'); if (res.ok) { const json = await res.json(); if (json.status === 'success') { userLibrary = json.data; } } } catch (err) { console.error('Erro ao buscar biblioteca no banco de dados:', err); } } document.addEventListener('DOMContentLoaded', async () => { await fetchServerLibrary(); if (!apiKey) { openKeyModal(); } else { fetchPopularMovies(); } if (window.lucide) lucide.createIcons(); }); function openKeyModal() { document.getElementById('api-key-input').value = apiKey; document.getElementById('key-modal').classList.remove('hidden'); } function saveApiKey(e) { e.preventDefault(); const val = document.getElementById('api-key-input').value.trim(); if (val) { apiKey = val; localStorage.setItem('gocine_tmdb_key', apiKey); document.getElementById('key-modal').classList.add('hidden'); fetchPopularMovies(); } } // Busca filmes populares do TMDb em PT-BR async function fetchPopularMovies() { const grid = document.getElementById('movies-grid'); grid.innerHTML = '<div class="col-span-full text-center py-10 text-gray-400">Carregando catálogo do TMDb...</div>'; try { const res = await fetch(`${TMDB_BASE_URL}/movie/popular?api_key=${apiKey}&language=pt-BR&page=1`); if (!res.ok) throw new Error('Chave de API inválida'); const data = await res.json(); renderMovies(data.results); } catch (err) { grid.innerHTML = ` <div class="col-span-full text-center py-10"> <p class="text-red-500 mb-4">Erro ao conectar com o TMDb. Verifique sua Chave de API.</p> <button onclick="openKeyModal()" class="bg-brand-red text-white px-4 py-2 rounded text-sm font-bold">Configurar Chave</button> </div> `; } } // Busca dinâmica por nome no TMDb async function searchMovies(query) { if (!query.trim()) { fetchPopularMovies(); return; } try { const res = await fetch(`${TMDB_BASE_URL}/search/multi?api_key=${apiKey}&language=pt-BR&query=${encodeURIComponent(query)}&page=1`); const data = await res.json(); const filtered = data.results.filter(item => (item.media_type === 'movie' || item.media_type === 'tv') && item.poster_path); renderMovies(filtered); } catch (err) { console.error(err); } } let searchTimeout; function handleSearch(e) { clearTimeout(searchTimeout); const query = e.target.value; searchTimeout = setTimeout(() => { if (currentSection !== 'search') showSection('search'); searchMovies(query); }, 300); } function showSection(section) { currentSection = section; const titles = { search: 'Filmes Populares (PT-BR)', liked: 'Meus Curtidos', watched: 'Já Assisti', watchlist: 'Pretendo Assistir' }; document.getElementById('section-title').innerHTML = ` <i data-lucide="film" class="text-brand-red"></i> ${titles[section]} `; if (section === 'search') { const q = document.getElementById('search-input').value; if (q) searchMovies(q); else fetchPopularMovies(); } else { loadSavedCategory(section); } if (window.lucide) lucide.createIcons(); } // Carrega os títulos salvos a partir da biblioteca sincronizada async function loadSavedCategory(category) { const items = userLibrary[category] || []; const grid = document.getElementById('movies-grid'); grid.innerHTML = ''; document.getElementById('item-count').textContent = `${items.length} título(s)`; if (items.length === 0) { grid.innerHTML = `<p class="col-span-full text-center text-gray-500 py-12">Nenhum título adicionado a esta lista ainda.</p>`; return; } grid.innerHTML = '<div class="col-span-full text-center py-10 text-gray-400">Carregando seus títulos...</div>'; const loadedList = []; for (const obj of items) { try { const type = obj.type || 'movie'; const res = await fetch(`${TMDB_BASE_URL}/${type}/${obj.id}?api_key=${apiKey}&language=pt-BR`); const data = await res.json(); data.media_type = type; loadedList.push(data); } catch (err) { console.error(err); } } renderMovies(loadedList); } function renderMovies(items) { const grid = document.getElementById('movies-grid'); grid.innerHTML = ''; document.getElementById('item-count').textContent = `${items.length} títulos encontrados`; if (!items || items.length === 0) { grid.innerHTML = `<p class="col-span-full text-center text-gray-500 py-12">Nenhum resultado encontrado.</p>`; return; } items.forEach(item => { grid.appendChild(createMovieCard(item)); }); if (window.lucide) lucide.createIcons(); } function createMovieCard(item) { const card = document.createElement('div'); card.className = 'bg-brand-card border border-brand-border rounded-lg overflow-hidden group hover:border-brand-red transition duration-300 flex flex-col justify-between'; const type = item.media_type || (item.first_air_date ? 'tv' : 'movie'); const title = item.title || item.name || 'Sem título'; const rating = item.vote_average ? item.vote_average.toFixed(1) : 'N/A'; const poster = item.poster_path ? `${IMAGE_BASE_URL}${item.poster_path}` : 'https://via.placeholder.com/500x750?text=Sem+Imagem'; const isLiked = userLibrary.liked.some(x => x.id === item.id); const isWatched = userLibrary.watched.some(x => x.id === item.id); const isWatchlist = userLibrary.watchlist.some(x => x.id === item.id); card.innerHTML = ` <div class="relative cursor-pointer overflow-hidden" onclick="openDetailsModal(${item.id}, '${type}')"> <img src="${poster}" alt="${title}" class="w-full h-72 object-cover group-hover:scale-105 transition duration-300"> <div class="absolute top-2 right-2 bg-black/80 px-2 py-1 rounded text-xs text-yellow-400 font-bold flex items-center gap-1"> <i data-lucide="star" class="w-3 h-3 fill-yellow-400"></i> ${rating} </div> </div> <div class="p-4 flex-1 flex flex-col justify-between"> <h3 class="font-bold text-sm text-white line-clamp-1 mb-3 cursor-pointer hover:text-brand-red" onclick="openDetailsModal(${item.id}, '${type}')">${title}</h3> <div class="flex items-center justify-between border-t border-brand-border pt-3"> <button onclick="toggleStatus(event, ${item.id}, '${type}', 'liked')" title="Curtir" class="p-1 rounded ${isLiked ? 'text-brand-red' : 'text-gray-400 hover:text-white'}"> <i data-lucide="heart" class="w-5 h-5 ${isLiked ? 'fill-brand-red' : ''}"></i> </button> <button onclick="toggleStatus(event, ${item.id}, '${type}', 'watched')" title="Já Assisti" class="p-1 rounded ${isWatched ? 'text-green-500' : 'text-gray-400 hover:text-white'}"> <i data-lucide="check-circle" class="w-5 h-5 ${isWatched ? 'fill-green-500' : ''}"></i> </button> <button onclick="toggleStatus(event, ${item.id}, '${type}', 'watchlist')" title="Pretendo Assistir" class="p-1 rounded ${isWatchlist ? 'text-blue-500' : 'text-gray-400 hover:text-white'}"> <i data-lucide="bookmark" class="w-5 h-5 ${isWatchlist ? 'fill-blue-500' : ''}"></i> </button> </div> </div> `; return card; } // Alterna o status chamando o endpoint do servidor em index.php async function toggleStatus(event, itemId, type, listName) { event.stopPropagation(); try { const res = await fetch('index.php?action=toggle_item', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ item_id: itemId, tipo: type, lista: listName }) }); if (res.ok) { await fetchServerLibrary(); if (currentSection === 'search') { const q = document.getElementById('search-input').value; if (q) searchMovies(q); else fetchPopularMovies(); } else { loadSavedCategory(currentSection); } } } catch (err) { console.error('Erro ao conectar ao servidor:', err); } } // Modal de Detalhes async function openDetailsModal(itemId, type) { const modal = document.getElementById('details-modal'); const content = document.getElementById('modal-content'); content.innerHTML = `<div class="text-center py-8 text-gray-400">Carregando detalhes do TMDb...</div>`; modal.classList.remove('hidden'); try { const res = await fetch(`${TMDB_BASE_URL}/${type}/${itemId}?api_key=${apiKey}&language=pt-BR`); const item = await res.json(); const title = item.title || item.name; const year = (item.release_date || item.first_air_date || '').split('-')[0] || 'N/A'; const genres = item.genres ? item.genres.map(g => g.name).join(', ') : 'Geral'; const overview = item.overview || 'Sinopse não disponível em português para este título.'; const poster = item.poster_path ? `${IMAGE_BASE_URL}${item.poster_path}` : 'https://via.placeholder.com/500x750?text=Sem+Imagem'; content.innerHTML = ` <div class="flex flex-col md:flex-row gap-6"> <img src="${poster}" alt="${title}" class="w-full md:w-48 h-72 object-cover rounded-lg shadow-lg"> <div class="flex-1"> <h2 class="text-2xl font-bold text-white mb-1">${title}</h2> <p class="text-xs text-gray-400 mb-3">${year} • ${genres}</p> <h4 class="text-sm font-semibold text-brand-red mb-1">Sinopse em Português</h4> <p class="text-sm text-gray-300 mb-4 leading-relaxed">${overview}</p> <div class="inline-flex items-center gap-2 bg-brand-dark border border-brand-border px-3 py-1.5 rounded-lg text-xs text-white font-medium"> <span>⭐ Avaliação TMDb:</span> ${item.vote_average ? item.vote_average.toFixed(1) : 'N/A'} / 10 </div> </div> </div> `; if (window.lucide) lucide.createIcons(); } catch (err) { content.innerHTML = `<div class="text-center py-8 text-red-500">Erro ao carregar detalhes.</div>`; } } function closeDetailsModal() { document.getElementById('details-modal').classList.add('hidden'); document.getElementById('modal-content').innerHTML = ''; } </script> </body> </html>